# 直到 lit_manual_import 才按「≤30 页 + 首页 SI 抬头 + 无摘要」识别为 SI。
SI_HREF_KEYS = ("suppl", "supplement", "supporting", "mmc", "/si/", "_si.", "-si.")


def is_si_href(href: str) -> bool:
    low = (href or "").strip().lower()
    return any(k in low for k in SI_HREF_KEYS)


def _swallow_future(fut) -> None:
    """取走 future 的异常，避免 `Task exception was never retrieved` 噪声。

    `click_si_download` 同时挂 `download` / `popup` 两个 wait_for_event，
    先到先得、另一个 cancel。被 cancel 的那个在 GC 时会打印整段 Playwright
    Traceback（实测 ACS SI 点击路径每篇一条），把真正的失败原因淹没。
    """
    try:
        fut.exception()
    except BaseException:  # noqa: BLE001  CancelledError / TimeoutError
        pass


def si_href_key(href: str) -> str:
    """SI 链接的比对键（用于「这条 href 在页面上对应哪个 <a>」）。

    🔴 2026-10-26 实测：ACS 的文件链接常写成
    `https://pubs.acs.org/doi/suppl/<doi>/article-supplement/<id>/pdf/<suffix>_si_001/`
    ——**以 `/` 结尾**，`os.path.basename(path)` 直接返回空串，
    于是 click_si_download 的 `target in h` 永远不成立，整批 ACS SI 都报
    `no_element_for_href`（10 篇实测全中）。这里 rstrip("/") 后再取末段。
    """
    path = urllib.parse.urlparse(href or "").path
    path = path.rstrip("/")
    return os.path.basename(path)


def si_href_matches(target_abs: str, cand_href: str, base_url: str = "") -> bool:
    """页面上某个 `<a href=cand_href>` 是否就是要找的 SI 链接 `target_abs`。

    两种匹配都接受：① 归一化后绝对 URL 相同（页面上的 href 常是相对路径）；
    ② 末段文件名出现在候选 URL 里（ACS/Wiley 的查询串形态）。
    """
    if not target_abs or not cand_href:
        return False
    cand_abs = urllib.parse.urljoin(base_url or "", cand_href)
    if cand_abs.rstrip("/") == target_abs.rstrip("/"):
        return True
    key = si_href_key(target_abs)
    return bool(key) and key in cand_abs


def existing_si_files(si_dir: str, stem: str) -> list[str]:
    """返回已在库的 SI 实体文件（`<stem>.si.<ext>` / `.si2.<ext>` …）。

    用途：避免每一轮都把「主文已下、SI 早已在 raw/pdf/si」的条目重新送进浏览器。
    只看非空文件；`present` 必须对应真实文件，不能靠推断。
    """
    if not si_dir or not stem or not os.path.isdir(si_dir):
        return []
    prefix = stem + ".si"
    out = []
    try:
        for name in os.listdir(si_dir):
            if not name.startswith(prefix):
                continue
            p = os.path.join(si_dir, name)
            try:
                if os.path.isfile(p) and os.path.getsize(p) > 0:
                    out.append(p)
            except OSError:
                pass
    except OSError:
        return []
    return sorted(out)


