def _now() -> str:
    return _dt.datetime.now().strftime("%Y%m%d-%H%M%S")


def _today() -> str:
    return _dt.date.today().isoformat()


def _rel(path: str) -> str:
    try:
        return os.path.relpath(path, VAULT).replace("\\", "/")
    except Exception:  # noqa: BLE001
        return path.replace("\\", "/")


def _resolve(path: str) -> str:
    if not path:
        return path
    return path if os.path.isabs(path) else os.path.join(VAULT, path)


def _atomic_write(path: str, data: bytes) -> None:
    os.makedirs(os.path.dirname(os.path.abspath(path)) or ".", exist_ok=True)
    tmp = path + ".part"
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def _atomic_text(path: str, text: str) -> None:
    _atomic_write(path, text.encode("utf-8"))


# --- 专用 profile 的残留 Edge 清理（仅 Windows） ---------------------------
# 事故：上一轮 Edge 没退干净，profile 仍被锁；新实例打印“在现有浏览器会话中打开”
# 后立刻退出，Playwright 拿到一个已死的 context，后续所有 new_page 都 TargetClosed。
# 只匹配命令行里含本专用 profile 路径的 msedge，绝不碰日常 Edge。
def _profile_edge_count(profile: str) -> int:
    if os.name != "nt" or not profile:
        return 0
    q = os.path.abspath(profile).replace("'", "''")
    script = (
        "@(Get-CimInstance Win32_Process -Filter \"Name='msedge.exe'\" | "
        f"Where-Object {{ $_.CommandLine -like '*{q}*' }}).Count"
    )
    try:
        cp = subprocess.run(
            ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=30)
        out = (cp.stdout or "").strip().splitlines()
        return int(out[-1].strip()) if out and out[-1].strip().isdigit() else 0
    except Exception:  # noqa: BLE001
        return 0


def kill_profile_edge(profile: str) -> int:
    """强杀使用本专用 profile 的 msedge；返回清理数量。只在重启/无人值守启动时用。"""
    if os.name != "nt" or not profile:
        return 0
    q = os.path.abspath(profile).replace("'", "''")
    # /T 连子进程一起杀：只杀主进程时，GPU/utility/crashpad 子进程可能继续持有 profile
    script = (
        "$p=@(Get-CimInstance Win32_Process -Filter \"Name='msedge.exe'\" | "
        f"Where-Object {{ $_.CommandLine -like '*{q}*' }});"
        "$n=$p.Count;"
        "$p | ForEach-Object { & taskkill /PID $_.ProcessId /T /F 2>$null | Out-Null };"
        "Write-Output $n"
    )
    try:
        cp = subprocess.run(
            ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=30)
        out = (cp.stdout or "").strip().splitlines()
        return int(out[-1].strip()) if out and out[-1].strip().isdigit() else 0
    except Exception:  # noqa: BLE001
        return 0


def remove_stale_profile_lock(profile: str) -> bool:
    """只在没有进程占用 profile 时移除 Chromium 的 lockfile。"""
    if not profile or _profile_edge_count(profile) > 0:
        return False
    lock = os.path.join(profile, "lockfile")
    try:
        if os.path.exists(lock):
            os.remove(lock)
            return True
    except OSError:
        pass
    return False


class ProfileLock:
    """同一专用 profile 的跨进程互斥锁（OS 级，进程退出自动释放）。

    为什么必须有：2026-10-26 实测两个后台任务同时跑本工具（一个补 SI 分块、
    一个补正文），各自的“清理残留 Edge”把对方的浏览器当孤儿杀掉，双方交替
    报 TargetClosedError / page_closed，看起来像“Edge 不稳定”，实际是互相踩。
    锁文件放 profile 同级目录（不在 profile 内，避免污染 Chromium 数据目录）。
    """

    def __init__(self, path: str):
        self.path = path
        self.fh = None

    def acquire(self) -> bool:
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        fh = open(self.path, "a+", encoding="utf-8")
        try:
            fh.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
            else:  # pragma: no cover - 本机为 Windows
                import fcntl
                fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            info = ""
            try:
                fh.seek(0)
                info = (fh.read(300) or "").strip()
            except Exception:  # noqa: BLE001  持有锁时读也可能被拒
                pass
            fh.close()
            print(f"[错误] 专用 profile 正被另一个进程占用：{info or '(未知)'}")
            print("       等它结束后再跑（两个实例会互相清理对方的 Edge）；"
                  "确需并行请加 --no-lock 并给不同 --profile。")
            return False
        try:
            fh.seek(0)
            fh.truncate()
            fh.write(f"{os.getpid()} {_now()} {os.path.basename(sys.argv[0])}\n")
            fh.flush()
        except Exception:  # noqa: BLE001
            pass
        self.fh = fh
        return True

    def release(self) -> None:
        fh, self.fh = self.fh, None
        if fh is None:
            return
        try:
            if os.name == "nt":
                import msvcrt
                fh.seek(0)
                msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
        except Exception:  # noqa: BLE001
            pass
        try:
            fh.close()
        except Exception:  # noqa: BLE001
            pass


def _norm_doi(s: str) -> str:
    d = (s or "").strip()
    d = re.sub(r"^https?://(dx\.)?doi\.org/", "", d, flags=re.I)
    d = re.sub(r"^doi:\s*", "", d, flags=re.I)
    d = d.strip().rstrip(".,;)]}>")
    return d.lower()


def _clean_title(s: str) -> str:
    s = re.sub(r"<[^>]+>", "", s or "")
    s = re.sub(r"\s+", " ", s).strip()
    return s


def looks_pdf_bytes(buf: bytes, ctype: str = "") -> bool:
    """优先用 lit_fetch.looks_pdf（本库唯一真伪闸门）；导入失败才退回本地实现。"""
    try:
        import lit_fetch
        return bool(lit_fetch.looks_pdf(buf, ctype))
    except Exception:  # noqa: BLE001
        if not buf or len(buf) < 1024:
            return False
        head = buf[:1024]
        if b"%PDF-" not in head:
            return False
        low = head[:512].lower()
        if b"<html" in low or b"<!doctype" in low:
            return False
        return True


def looks_pdf_file(path: str) -> bool:
    try:
        with open(path, "rb") as f:
            return looks_pdf_bytes(f.read(2048))
    except OSError:
        return False


def filename_for(item: "Item") -> str:
    """与 lit_fetch.pdf_filename 完全同口径，确保 lit_manual_import 能配上。"""
    try:
        import lit_fetch
        return lit_fetch.pdf_filename(asdict(item))
    except Exception:  # noqa: BLE001
        pass
    title = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "-", item.title or item.doi or "untitled")
    title = re.sub(r"\s+", " ", title).strip()
    jrn = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "-", item.journal or "Unknown")
    jrn = re.sub(r"\s+", " ", jrn).strip()
    year = (item.publication_date or "")[:4]
    if not re.match(r"^\d{4}$", year):
        year = "YYYY"
    return f"{title} - {jrn} - {year}.pdf"


def _probable_file_url(url: str) -> bool:
    low = (url or "").lower()
    return any(k in low for k in (
        ".pdf", ".docx", ".xlsx", ".zip", ".doc", ".csv", ".txt",
        "downloadsupplement", "suppl_file", "/article-supplement/",
    ))


def nav_download_first(url: str) -> bool:
    """这类 SI 链接应该**先走浏览器的下载通道**，而不是页内 fetch / 点击空等。

    ACS 的 `.../article-supplement/<id>/pdf/<suffix>_si_001/`（**以 `/` 结尾**、
    目录形态）就是"导航即下载"：`goto` 抛 `Download is starting`，页内 fetch 拿到
    145 MB 的 Content-Length 被 100 MB 上限挡下，`ctx.request` 则 403（2026-10-26 实测）。
    """
    low = (url or "").lower()
    path = urllib.parse.urlparse(url or "").path
    return "/article-supplement/" in low and path.endswith("/")


def _safe_domain(url: str) -> str:
    try:
        return urllib.parse.urlparse(url).hostname or ""
    except Exception:  # noqa: BLE001
        return ""


def _domain_matches(cookie_domain: str, host: str) -> bool:
    d = (cookie_domain or "").lstrip(".")
    return bool(d) and (host == d or host.endswith("." + d))


