# 主流程
# ---------------------------------------------------------------------------
def print_plan(items: list[Item], input_path: str, skipped: list[Item], dry_run: bool = True) -> None:
    print(f"[输入] {_rel(input_path)}")
    print(f"[计划] 待处理 {len(items)} 篇；预检跳过 {len(skipped)} 篇")
    for i, it in enumerate(items, 1):
        kind = "SI" if it.kind == "si" else "正文"
        print(f"  {i:>2}. [{it.publisher or '?':<16}] {kind} {it.doi or '(无DOI)'}  {(it.title or '')[:64]}")
    for it in skipped[:5]:
        print(f"  ⏭️ {it.doi or it.title[:50]} — {it.reason}")
    if len(skipped) > 5:
        print(f"  ⏭️ … 另有 {len(skipped) - 5} 篇跳过")
    if dry_run:
        print("\n[提示] 当前是干跑；加 --apply 才会真正启动浏览器下载。")


async def run_browser(args, items: list[Item], input_path: str, started: float) -> int:
    cfg = None
    try:
        import kb_lib as K
        cfg = K.load_lit_config()
    except Exception:  # noqa: BLE001
        pass
    pdf_dir = _resolve((cfg or {}).get("paths", {}).get("pdf_dir") or "raw/pdf") if cfg else _resolve("raw/pdf")
    inbox = args.outdir or os.path.join(pdf_dir, "Manual Download")
    inbox = _resolve(inbox)
    si_dir = _resolve(args.si_dir) if args.si_dir else os.path.join(pdf_dir, "si")
    os.makedirs(inbox, exist_ok=True)
    os.makedirs(si_dir, exist_ok=True)

    # profile / state
    profile = _resolve(args.profile)
    if args.fresh_profile:
        profile = profile + "-" + _now()
    # 同一 profile 只能有一个驱动进程：两个实例会互相把对方的 Edge 当残留清掉。
    lock = None
    if not getattr(args, "no_lock", False):
        lock = ProfileLock(os.path.join(os.path.dirname(profile), "profile.lock"))
        if not lock.acquire():
            return 2
    state_path = _resolve(args.state)
    state = {}
    try:
        state = _read_json(state_path)
        if not isinstance(state, dict):
            state = {}
    except Exception:  # noqa: BLE001
        state = {}
    domains = state.setdefault("domains", {})

    if args.reset_profile:
        if not args.apply:
            print(f"[干跑] 将把 profile 备份为 {_rel(profile)}.bak-<时间戳>（加 --apply 执行）")
            return 0
        if os.path.exists(profile):
            bak = profile + ".bak-" + _now()
            shutil.move(profile, bak)
            print(f"[reset] profile 已备份：{_rel(bak)}")
        if os.path.exists(state_path):
            os.remove(state_path)
        print("[reset] profile state 已清空")
        return 0

    session = BrowserSession(
        profile,
        headless=args.headless,
        interactive=args.interactive,
        human_timeout=args.human_timeout,
        channel=args.channel,
        delay_min=args.delay_min,
        delay_max=args.delay_max,
    )
    try:
        await session.launch()
    except Exception as e:  # noqa: BLE001
        print(f"[错误] 浏览器启动失败：{e}")
        return 2

    results: list[Item] = []
    try:
        # 按域名分组，保持首次出现顺序
        order: list[str] = []
        groups: dict[str, list[Item]] = {}
        for it in items:
            key = it.recipe or "generic"
            if key not in groups:
                groups[key] = []
                order.append(key)
            groups[key].append(it)

        for key in order:
            domain = key
            ds = domains.setdefault(domain, {"fails": 0, "needs_human": False, "at": ""})
            # 无人值守：若 6 小时内被标记 needs_human，直接跳过该域
            if (not args.interactive) and ds.get("needs_human"):
                at = ds.get("at") or ""
                try:
                    age = (time.time() - _dt.datetime.fromisoformat(at).timestamp()) if at else 99999
                except Exception:  # noqa: BLE001
                    age = 99999
                if age < 6 * 3600:
                    for it in groups[key]:
                        it.status = it.status or "failed"
                        it.reason = it.reason or "该域名 6 小时内需人工验证过；无人值守模式跳过（用 --interactive）"
                        results.append(it)
                    print(f"[skip] {domain}：6 小时内被标记需人工验证，整组跳过")
                    continue
            # 上一个域可能因页面自杀/Edge 退出把整个上下文带走；先探活并必要时重启。
            page = None
            if await session.ensure_ready():
                try:
                    page = await session.ctx.new_page()
                except Exception as e:  # noqa: BLE001
                    print(f"[warn] 新建页面失败：{type(e).__name__}: {e}")
            if page is None:
                for it in groups[key]:
                    it.status = it.status or "failed"
                    it.reason = it.reason or "浏览器不可用（上下文已关闭且重启失败）"
                    results.append(it)
                print(f"[fail] {domain}：浏览器不可用，整组记为失败")
                continue
            try:
                for it in groups[key]:
                    if page.is_closed():
                        try:
                            page = await session.ctx.new_page()
                        except Exception as e:  # noqa: BLE001
                            it.status = it.status or "failed"
                            it.reason = it.reason or f"browser_closed: {type(e).__name__}"
                            results.append(it)
                            continue
                    if it.kind == "si":
                        # SI 项在主文阶段之后单独处理
                        results.append(it)
                        continue
                    dest = os.path.join(inbox, filename_for(it))
                    if os.path.exists(dest) and looks_pdf_file(dest):
                        it.status, it.dest, it.size = "ok", dest, os.path.getsize(dest)
                        it.method, it.reason = "已存在", ""
                        print(f"[ok] 已存在：{os.path.basename(dest)}")
                        results.append(it)
                        continue
                    print(f"\n[fetch] {it.publisher} | {it.doi} | {(it.title or '')[:70]}")
                    try:
                        ok, method, err = await session.download_main(page, it, dest)
                    except Exception as e:  # noqa: BLE001
                        ok, method, err = False, "", f"{type(e).__name__}: {str(e)[:160]}"
                    if not ok and err == "page_closed":
                        # 站点/挑战页把承载页面自杀。上下文可能还在——重建页面再试一次；
                        # 若上下文也死了，ensure_ready() 会走 profile 清理 + 重启。
                        it.attempts.append("page_closed: 重建页面重试")
                        try:
                            await session.polite_sleep()
                            if await session.ensure_ready():
                                page = await session.ctx.new_page()
                                ok, method, err = await session.download_main(page, it, dest)
                            else:
                                err = "浏览器不可用（重建页面失败）"
                        except Exception as e:  # noqa: BLE001
                            ok, method, err = False, "", f"retry_{type(e).__name__}: {str(e)[:140]}"
                    if ok:
                        it.status, it.dest, it.size = "ok", dest, os.path.getsize(dest)
                        it.method, it.reason = method, ""
                        ds["fails"] = 0
                        ds["needs_human"] = False
                        print(f"[ok] {method} -> {os.path.basename(dest)} ({it.size/1e6:.1f} MB)")
                    else:
                        it.status, it.reason = "failed", err or "未取到真 PDF"
                        # `page_closed` 是浏览器/页面生命周期问题，不是出版社风控；
                        # 把它计入 fails 会让域名被错误标记 needs_human 6 小时。
                        if err in ("captcha_requires_human", "botmanager_requires_human",
                                   "challenge_timeout", "human_timeout"):
                            ds["fails"] = int(ds.get("fails") or 0) + 1
                            if ds["fails"] >= 2:
                                ds["needs_human"] = True
                                ds["at"] = _dt.datetime.now().isoformat(timespec="seconds")
                                print(f"[stop] {domain} 连续 {ds['fails']} 次风控，本域停止")
                        print(f"[fail] {it.reason[:160]}")
                    results.append(it)
                    await session.polite_sleep()
            finally:
                try:
                    await page.close()
                except Exception:  # noqa: BLE001
                    pass
            # 每域结束后写一次 state
            try:
                _atomic_text(state_path, json.dumps(state, ensure_ascii=False, indent=1))
            except Exception:  # noqa: BLE001
                pass

        # ---- 收编 ----
        ledger_map: dict[str, str] = {}
        if args.import_:
            print("\n[import] 运行 lit_manual_import.py --apply ...")
            try:
                import lit_manual_import as LMI
                ledger = LMI.ledger_path()
                cmd = [sys.executable, os.path.join(HERE, "lit_manual_import.py"),
                       "--inbox", inbox, "--apply"]
                env = dict(os.environ, PYTHONIOENCODING="utf-8")
                cp = subprocess.run(cmd, cwd=VAULT, capture_output=True, text=True,
                                    encoding="utf-8", errors="replace", timeout=600, env=env)
                tail = (cp.stdout or "")[-1800:]
                if tail:
                    print(tail)
                if cp.returncode != 0:
                    print(f"[warn] lit_manual_import 退出码 {cp.returncode}：{(cp.stderr or '')[-500:]}")
                if os.path.exists(ledger):
                    for rec in _read_json(ledger):
                        d = _norm_doi(rec.get("doi") or "")
                        if d and rec.get("dst"):
                            ledger_map[d] = rec["dst"]
            except Exception as e:  # noqa: BLE001
                print(f"[warn] 收编失败：{type(e).__name__}: {e}")

        # ---- SI ----
        if not args.no_si:
            si_items = []
            for it in results:
                if it.kind == "si":
                    # SI-only 输入通常只给 DOI；主文可能早已在 raw/pdf 或本地目录里。
                    if not (it.pdf_path and os.path.exists(it.pdf_path)):
                        found = find_existing_pdf(it)
                        if found:
                            it.pdf_path = found
                    if it.pdf_path and os.path.exists(it.pdf_path):
                        si_items.append(it)
                    else:
                        it.si_status, it.si_reason = "missing", "未找到主文 PDF，无法取 SI"
                        print(f"[si] 未找到主文：{it.doi}")
                elif it.status == "ok":
                    main_pdf = ledger_map.get(it.doi) or it.dest
                    if main_pdf and os.path.exists(main_pdf):
                        it.pdf_path = main_pdf
                        si_items.append(it)
            # 已在库的 SI 先摘出去：不依赖浏览器，也不会因浏览器死亡被误报 missing。
            if si_items:
                pending_si = []
                for it in si_items:
                    stem = os.path.splitext(os.path.basename(it.pdf_path or it.dest or ""))[0]
                    files = existing_si_files(si_dir, stem)
                    if files:
                        it.si_status, it.si_files, it.si_reason = "present", files, "已存在"
                    else:
                        pending_si.append(it)
                if pending_si:
                    si_items = pending_si
                else:
                    print(f"[si] 全部 {len(si_items)} 篇的 SI 已在库，跳过浏览器")
                    si_items = []
            if si_items:
                print(f"\n[si] 处理 {len(si_items)} 篇的补充材料 ...")
                # 主文阶段可能把浏览器带走（页面自杀 / Edge 退出）；SI 阶段先探活。
                page = None
                if await session.ensure_ready():
                    try:
                        page = await session.ctx.new_page()
                    except Exception as e:  # noqa: BLE001
                        print(f"[warn] 无法新建 SI 页面：{type(e).__name__}: {e}")
                if page is None:
                    for it in si_items:
                        it.si_status, it.si_reason = "missing", "浏览器不可用，SI 未处理"
                        print(f"[si] ⚠️ missing 浏览器不可用：{it.doi}")
                else:
                    try:
                        for it in si_items:
                            main_pdf = it.pdf_path or ledger_map.get(it.doi) or it.dest
                            if not main_pdf or not os.path.exists(main_pdf):
                                it.si_status, it.si_reason = "missing", "主文 PDF 不存在"
                                continue
                            print(f"[si] {it.doi} | {os.path.basename(main_pdf)}")
                            st, files, why = "missing", [], "未执行"
                            for attempt in (1, 2):
                                # 有的 SI 页/挑战页会把承载页面自杀（实测 2026-10-26：
                                # 第一篇 SI 成功后，同一 page 上后续 8 篇全报 page_closed）。
                                # 页面死了就重建；上下文也死了 ensure_ready() 会重启浏览器。
                                if page is None or page.is_closed():
                                    print("[warn] SI 页面已关闭，重建 ...")
                                    page = None
                                    try:
                                        if await session.ensure_ready():
                                            page = await session.ctx.new_page()
                                    except Exception as e:  # noqa: BLE001
                                        print(f"[warn] 重建 SI 页面失败：{type(e).__name__}: {e}")
                                    if page is None:
                                        st, files, why = "missing", [], "浏览器不可用，SI 未处理"
                                        break
                                mark_n = len(it.attempts)
                                try:
                                    st, files, why = await session.download_si(page, it, main_pdf, si_dir)
                                except Exception as e:  # noqa: BLE001
                                    st, files, why = "unknown", [], f"{type(e).__name__}: {str(e)[:140]}"
                                closed = page is None or page.is_closed()
                                retryable = closed or any("page_closed" in a for a in it.attempts[mark_n:])
                                if st == "present" or not retryable or attempt == 2:
                                    break
                                print("[warn] 取 SI 期间页面被关闭，重建后重试 ...")
                                try:
                                    if page is not None and not page.is_closed():
                                        await page.close()
                                except Exception:  # noqa: BLE001
                                    pass
                                page = None
                                await session.polite_sleep()
                            it.si_status, it.si_files, it.si_reason = st, files, why
                            mark = {"present": "✅", "not_applicable": "⛔", "missing": "⚠️"}.get(st, "❓")
                            print(f"  {mark} {st} {why}")
                            await session.polite_sleep()
                    finally:
                        try:
                            if page is not None:
                                await page.close()
                        except Exception:  # noqa: BLE001
                            pass
    finally:
        if args.keep_open:
            print("\n[keep-open] 浏览器保持打开；关闭窗口后脚本退出。")
        # close() 内部已含无人值守的残留进程清理；--keep-open 时保留浏览器。
        await session.close(keep_processes=args.keep_open)
        if lock is not None:
            lock.release()
        try:
            _atomic_text(state_path, json.dumps(state, ensure_ascii=False, indent=1))
        except Exception:  # noqa: BLE001
            pass

    # ---- 报告 ----
    stamp = _now()
    if args.report:
        report_path = _resolve(args.report)
        report_dir = os.path.dirname(report_path) or "."
        stem_base = os.path.splitext(os.path.basename(report_path))[0]
    else:
        report_dir = _resolve("raw/notes/lit-watch/downloads")
        stem_base = f"browser-fetch-{stamp}"
        report_path = os.path.join(report_dir, stem_base + ".md")
    os.makedirs(report_dir, exist_ok=True)
    residual_path = os.path.join(report_dir, f"{stem_base}-residual.md")
    residual = ""
    if not args.no_residual:
        residual = write_residual(results, residual_path, "浏览器兜底后剩余", inbox)
    report = render_report(results, input_path=input_path, mode=("apply/交互" if args.interactive else "apply/无人值守"),
                           started=started, known_skipped=0,
                           residual_path=residual)
    _atomic_text(report_path, report)
    json_path = os.path.join(report_dir, stem_base + ".json")
    _atomic_text(json_path, json.dumps([asdict(x) for x in results], ensure_ascii=False, indent=1))
    print(f"\n[report] {_rel(report_path)}")
    print(f"[json]   {_rel(json_path)}")
    if residual:
        print(f"[residual] {_rel(residual)}")
    else:
        print("[residual] 0 篇——本批不需要人工下载")

    ok_n = sum(1 for x in results if x.status == "ok")
    fail_n = sum(1 for x in results if x.status not in ("ok", "skipped"))
    si_missing = sum(1 for x in results if x.si_status == "missing")
    if not args.no_log:
        append_log(f"## [{_today()}] lit-browser-fetch | 输入 `{_rel(input_path)}`："
                   f"正文成功 {ok_n}/{ok_n + fail_n}，SI 仍缺 {si_missing}，"
                   f"残余清单 `{_rel(residual) if residual else '无'}`")
    return exit_code_for(results)


async def seed_from_profile(args) -> int:
    """把一个已通过验证的 profile 的 cookies 导入目标 profile（一次性引导）。

    用途：新机器/新 profile 第一次遇到 Cloudflare 时，自动点击可能过不去；
    若另一个 profile（例如你手动登录过的）已有 cf_clearance，可直接继承，
    省去每个出版商人工过一次。**不复制书签/历史/密码**，只导入出版商相关 cookie。
    """
    src = _resolve(args.seed_from)
    dst = _resolve(args.profile)
    if not os.path.isdir(src):
        print(f"[错误] 源 profile 不存在：{src}")
        return 2
    if os.path.exists(os.path.join(src, "SingletonLock")):
        print(f"[错误] 源 profile 正被 Edge 占用（有 SingletonLock）。请先完全退出 Edge。")
        return 2
    if not args.apply:
        print(f"[干跑] 将从 {_rel(src)} 导入出版商 cookies 到 {_rel(dst)}（加 --apply 执行）")
        return 0
    keep = (
        "sciencedirect", "elsevier", "acs.org", "wiley.com", "nature.com",
        "science.org", "rsc.org", "iop.org", "springer.com", "pnas.org",
        "aip.org", "aps.org", "hcaptcha.com", "cloudflare.com",
    )
    src_s = BrowserSession(src, headless=True, interactive=False, human_timeout=10,
                           channel=args.channel, verbose=False)
    try:
        await src_s.start()
        cookies = await src_s.ctx.cookies()
    except Exception as e:  # noqa: BLE001
        print(f"[错误] 读取源 profile 失败：{type(e).__name__}: {e}")
        return 2
    finally:
        await src_s.close()
    filtered = [c for c in cookies
                if any(k in (c.get("domain") or "").lower() for k in keep)]
    if not filtered:
        print("[warn] 源 profile 里没有找到出版商相关 cookies")
        return 3
    dst_s = BrowserSession(dst, headless=True, interactive=False, human_timeout=10,
                           channel=args.channel, verbose=False)
    try:
        await dst_s.start()
        await dst_s.ctx.add_cookies(filtered)
    except Exception as e:  # noqa: BLE001
        print(f"[错误] 写入目标 profile 失败：{type(e).__name__}: {e}")
        return 2
    finally:
        await dst_s.close()
    print(f"[seed] 已导入 {len(filtered)} 条 cookies -> {_rel(dst)}")
    for c in filtered:
        if c.get("name") in ("cf_clearance", "__cf_bm"):
            print(f"  · {c.get('domain')} {c.get('name')}")
    return 0


async def run_login(args) -> int:
    profile = _resolve(args.profile)
    session = BrowserSession(profile, headless=False, interactive=True,
                             human_timeout=args.human_timeout, channel=args.channel)
    try:
        await session.start()
    except Exception as e:  # noqa: BLE001
        print(f"[错误] 浏览器启动失败：{e}")
        return 2
    try:
        url = args.login_url or "https://www.sciencedirect.com/"
        print(f"[login] 打开 {url}")
        await session.goto(session.page, url)
        print("请在浏览器中完成机构登录 / CARSI / 验证。")
        print("完成后回到本终端按 Enter 保存会话（profile 会持久化）。")
        try:
            input()
        except EOFError:
            print("[warn] 非交互终端，等待 120 秒后自动关闭。")
            await asyncio.sleep(120)
    finally:
        await session.close()
    print("[login] 完成")
    return 0


def build_parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(
        description="用真实浏览器 + 类人鼠标兜底下载 lit-watch 失败的正文与 SI",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=__doc__.split("典型用法")[-1] if "典型用法" in __doc__ else "",
    )
    src = ap.add_argument_group("输入")
    src.add_argument("--in", dest="input", default="", help="picks/fetch_result JSON 或手动下载清单 md")
    src.add_argument("--latest", action="store_true", help="自动选最新仍有 failed/si_missing 的 fetch_result")
    src.add_argument("--doi", action="append", default=[], help="单篇 DOI（可重复）")
    src.add_argument("--no-metadata", action="store_true", help="不联网查 Crossref 补元数据")
    src.add_argument("--no-dedup", action="store_true", help="不按本机文献目录去重（仍跳过 raw/pdf 已有同名 PDF）")

    run = ap.add_argument_group("运行")
    run.add_argument("--apply", action="store_true", help="真正下载（默认干跑）")
    run.add_argument("--import", dest="import_", action="store_true", help="下载后运行 lit_manual_import.py --apply")
    run.add_argument("--interactive", action="store_true", help="遇到图片验证码时等待人工处理")
    run.add_argument("--headless", action="store_true", help="无头模式（会显著降低过验证率）")
    run.add_argument("--limit", type=int, default=DEFAULT_LIMIT, help=f"本轮最多处理篇数（默认 {DEFAULT_LIMIT}，0=不限）")
    run.add_argument("--only", default="", help="只处理这些出版商，逗号分隔：acs,wiley,elsevier,...")
    run.add_argument("--skip", default="", help="跳过这些出版商，逗号分隔")
    run.add_argument("--no-si", action="store_true", help="跳过 SI 阶段")
    run.add_argument("--outdir", default="", help="主文落点（默认 raw/pdf/Manual Download）")
    run.add_argument("--si-dir", default="", help="SI 落点（默认 raw/pdf/si；测试可改）")
    run.add_argument("--delay-min", type=float, default=DEFAULT_DELAY_MIN, help="篇间隔下限秒")
    run.add_argument("--delay-max", type=float, default=DEFAULT_DELAY_MAX, help="篇间隔上限秒")
    run.add_argument("--human-timeout", type=int, default=DEFAULT_HUMAN_TIMEOUT, help="交互模式单次人工等待秒")
    run.add_argument("--keep-open", action="store_true", help="结束后保持浏览器打开（调试用）")
    run.add_argument("--json", action="store_true", help="结束后打印机器可读 JSON")
    run.add_argument("--no-log", action="store_true", help="不写 wiki/log_ops.md（测试/演练用）")
    run.add_argument("--no-residual", action="store_true", help="不写残余手动清单（测试/演练用）")

    prof = ap.add_argument_group("浏览器 / profile")
    prof.add_argument("--profile", default=DEFAULT_PROFILE_REL, help=f"专用 profile（默认 {DEFAULT_PROFILE_REL}）")
    prof.add_argument("--state", default=DEFAULT_STATE_REL, help=f"域名健康状态文件（默认 {DEFAULT_STATE_REL}）")
    prof.add_argument("--channel", default="", help="msedge / chrome（默认自动探测）")
    prof.add_argument("--fresh-profile", action="store_true", help="本次使用带时间戳的新 profile")
    prof.add_argument("--no-lock", action="store_true",
                      help="不建 profile 互斥锁（默认加锁，防止两个进程互相清理对方的 Edge）")
    prof.add_argument("--reset-profile", action="store_true", help="把 profile 备份并清空状态（需 --apply）")
    prof.add_argument("--seed-from", default="", help="从另一个已验证 profile 导入出版商 cookies（需 --apply）")
    prof.add_argument("--login", action="store_true", help="打开浏览器做机构登录/CARSI，完成后按 Enter")
    prof.add_argument("--login-url", default="", help="--login 打开的 URL（默认 ScienceDirect 首页）")

    ap.add_argument("--report", default="", help="报告落点（默认 raw/notes/lit-watch/downloads/）")
    ap.add_argument("--selftest", action="store_true", help="自检（不启动浏览器）")
    return ap


def selftest() -> int:
    print("=== lit_browser_fetch --selftest ===")
    ok = fail = 0

    def chk(name: str, cond: bool, extra: str = "") -> None:
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    # 1) 出版商分流
    cases = [
        ("10.1002/anie.6960943", "wiley"),
        ("10.1021/acscatal.6c01770", "acs"),
        ("10.1016/j.jpowsour.2026.241374", "elsevier"),
        ("10.1038/s41467-026-70442-y", "nature"),
        ("10.1007/s12345-026-0001-2", "springer"),
        ("10.1126/sciadv.aef7481", "science"),
        ("10.1039/d6xx00001a", "rsc"),
        ("10.1149/1945-7111/ae7837", "iop"),
        ("10.1073/pnas.2610214123", "pnas"),
        ("10.1063/1.4812323", "aip"),
        ("10.1103/physrevlett.104.136403", "aps"),
        ("10.9999/unknown", "generic"),
    ]
    for doi, want in cases:
        got = classify_recipe(doi).key
        chk(f"分流 {doi} -> {want}", got == want, f"got={got}")

    # 1b) APS 文章页 /abstract/ -> PDF /pdf/ 直链猜测
    aps = "https://journals.aps.org/prl/abstract/10.1103/PhysRevLett.104.136403"
    chk("APS abstract→pdf 直链",
        guess_pdf_url(aps) == "https://journals.aps.org/prl/pdf/10.1103/PhysRevLett.104.136403",
        guess_pdf_url(aps))
    chk("非 APS 不猜 PDF", guess_pdf_url("https://example.org/article/1") == "")

    # 1c) SI 链接不得当正文（ACS 的 suppl_file/..._si.pdf 曾顶替正文）
    chk("SI 链接识别 ACS",
        is_si_href("https://pubs.acs.org/doi/suppl/10.1021/ja9b00911/suppl_file/ja9b00911_si.pdf"))
    chk("SI 链接识别 Wiley",
        is_si_href("https://onlinelibrary.wiley.com/action/downloadSupplement?doi=10.1002/x&file=x-sup-0001.pdf"))
    chk("正文 PDF 链接不误判", not is_si_href("https://pubs.acs.org/doi/pdf/10.1021/ja9b00911"))
    chk("APS 正文 PDF 不误判",
        not is_si_href("https://journals.aps.org/prl/pdf/10.1103/PhysRevLett.104.136403"))

    # 🆕 1d) SI 链接与页面上 <a> 的对照（2026-10-26：ACS 链接以 `/` 结尾，
    #    basename 为空 ⇒ click_si_download 永远找不到元素，10 篇实测报 no_element_for_href）
    acs_si = ("https://pubs.acs.org/doi/suppl/10.1021/jacs.6c10800/"
              "article-supplement/ja6c10800/pdf/ja6c10800_si_001/")
    chk("ACS 尾斜杠链接取到末段键",
        si_href_key(acs_si) == "ja6c10800_si_001", si_href_key(acs_si))
    chk("ACS 尾斜杠链接可被相对 href 命中",
        si_href_matches(acs_si, "/doi/suppl/10.1021/jacs.6c10800/"
                                "article-supplement/ja6c10800/pdf/ja6c10800_si_001/",
                        "https://pubs.acs.org/doi/suppl/10.1021/jacs.6c10800"))
    chk("反例：另一篇的 SI 链接不误中",
        not si_href_matches(acs_si, "/doi/suppl/10.1021/jacs.6c99999/ja6c99999_si_001/",
                            "https://pubs.acs.org"))
    science_si = "https://www.science.org/doi/suppl/10.1126/science.aas9100/suppl_file/aas9100_sm.pdf"
    chk("Science 文件名型链接可被命中",
        si_href_matches(science_si, "/doi/suppl/10.1126/science.aas9100/suppl_file/aas9100_sm.pdf",
                        "https://www.science.org/doi/10.1126/science.aas9100"))
    chk("反例：空 href 不匹配", not si_href_matches(science_si, "", "https://x.org"))
    # 1f) 「导航即下载」的链接形态（ACS 目录型端点）：必须先走下载通道
    chk("ACS 目录型 SI 端点 → 先走下载通道", nav_download_first(acs_si))
    chk("反例：带扩展名的 SI 文件不先走下载通道",
        not nav_download_first(science_si))

    # 1e) 被 cancel 的 future 不得再抛「Task exception was never retrieved」
    async def _never_finishes():
        await asyncio.sleep(5)

    async def _probe_cancel():
        t = asyncio.ensure_future(_never_finishes())
        t.cancel()
        _swallow_future(t)
        await asyncio.sleep(0)
        return True

    chk("被 cancel 的 future 异常被吞掉", asyncio.run(_probe_cancel()))

    # 2) PDF 真伪闸门（正例 + 反例）
    chk("正例 %PDF-1.7", looks_pdf_bytes(b"%PDF-1.7\n" + b"x" * 2000))
    chk("反例 HTML 里提 %PDF", not looks_pdf_bytes(b"<html>%PDF-1.7</html>" + b"x" * 2000))
    chk("反例 空缓冲", not looks_pdf_bytes(b""))
    chk("反例 只有 %PDF 无 -", not looks_pdf_bytes(b"%PDF junk" + b"x" * 2000))

    # 3) 文件名合法
    fn = filename_for(Item(title='A/B: "C" <D>', journal="Nat. Commun.",
                           publication_date="2026-01-02"))
    chk("文件名无非法字符", not re.search(r'[<>:"/\\|?*]', fn), fn)
    chk("文件名以 .pdf 结尾", fn.endswith(".pdf"), fn)

    # 4) fetch_result 解析
    tmp = None
    try:
        import kb_lib as K
        tmp = K.make_temp_dir(prefix="litbf_selftest_")
        fr = os.path.join(tmp, "fetch_result-x.json")
        _atomic_text(fr, json.dumps({
            "ok": [{"doi": "10.1002/a", "pdf": "/x/a.pdf"}],
            "failed": [{"title": "Paper A", "doi": "10.1021/b", "journal": "JACS",
                        "oa_url": "https://x", "reasons": ["403"]}],
            "si_missing": [{"title": "Paper A", "doi": "10.1002/a", "reason": "SI 403"}],
        }, ensure_ascii=False))
        items = parse_fetch_result(fr)
        chk("fetch_result 解析出 2 条", len(items) == 2, str(len(items)))
        chk("failed 项字段", items[0].doi == "10.1021/b" and items[0].journal == "JACS")
        chk("si_missing 映射主文路径", items[1].kind == "si" and items[1].pdf_path.endswith("a.pdf"))

        # 5) picks 解析
        pk = os.path.join(tmp, "picks-x.json")
        _atomic_text(pk, json.dumps({"papers": [{
            "title": "Paper B", "doi": "10.1038/c", "journal": "Nature",
            "publication_date": "2026-03-04",
        }]}, ensure_ascii=False))
        items2 = parse_picks(pk)
        chk("picks 解析", len(items2) == 1 and items2[0].doi == "10.1038/c")

        pk2 = os.path.join(tmp, "picks-si.json")
        _atomic_text(pk2, json.dumps({"papers": [{
            "title": "Paper B", "doi": "10.1038/c", "kind": "si",
            "pdf_path": "/x/b.pdf",
        }]}, ensure_ascii=False))
        items2b = parse_picks(pk2)
        chk("picks 支持 SI 项",
            items2b[0].kind == "si" and items2b[0].pdf_path.endswith("b.pdf"))

        # 5b) 已在库的 SI 实体文件识别（不重复送浏览器，也不误报 missing）
        si_dir = os.path.join(tmp, "si")
        os.makedirs(si_dir, exist_ok=True)
        _atomic_write(os.path.join(si_dir, "Paper B.si.pdf"), b"%PDF-1.7\n" + b"x" * 100)
        _atomic_write(os.path.join(si_dir, "Empty.si.pdf"), b"")
        chk("已有 SI 文件识别", len(existing_si_files(si_dir, "Paper B")) == 1)
        chk("SI 前缀不误匹配", existing_si_files(si_dir, "Paper") == [])
        chk("空 SI 文件不算 present", existing_si_files(si_dir, "Empty") == [])

        # 5c) 本地目录 DOI→主文 PDF；SI 不得冒充主文
        old_vault = globals().get("VAULT")
        try:
            globals()["VAULT"] = tmp
            pdf_ok = os.path.join(tmp, "main.pdf")
            _atomic_write(pdf_ok, b"%PDF-1.7\n" + b"x" * 100)
            catp = os.path.join(tmp, "raw", "notes", "lit-watch", "state",
                                "local_lit_catalogue.json")
            os.makedirs(os.path.dirname(catp), exist_ok=True)
            _atomic_text(catp, json.dumps({"papers": [
                {"doi": "10.1002/ok", "local_files": [{"path": pdf_ok}]},
                {"doi": "10.1002/si", "local_files": [{"path": os.path.join(si_dir, "Paper B.si.pdf")}]},
            ]}, ensure_ascii=False))
            chk("catalogue DOI→主文 PDF", find_catalogue_pdf("10.1002/OK") == pdf_ok)
            chk("catalogue 不把 SI 当主文", find_catalogue_pdf("10.1002/si") == "")
        finally:
            globals()["VAULT"] = old_vault

        # 6) manifest 解析（主文 + SI）
        mf = os.path.join(tmp, "manifest-x.md")
        _atomic_text(mf, """# 手动下载清单

### 1. Paper C
- **期刊**：JACS（2026-05-06）
- **DOI**：[10.1021/d](https://doi.org/10.1021/d)
- **OA 页**：[打开](https://pubs.acs.org/doi/10.1021/d)
- 自动失败原因：`403`

## 📎 SI 待手动下载

### S1. Paper C
- **DOI**：[10.1021/d](https://doi.org/10.1021/d)
- **SI 页**：[ACS SI 专题页](https://pubs.acs.org/doi/suppl/10.1021/d)
""")
        items3 = parse_manifest(mf)
        chk("manifest 解析出 2 条", len(items3) == 2, str(len(items3)))
        chk("manifest 主文 DOI/journal", items3[0].doi == "10.1021/d" and "JACS" in items3[0].journal)
        chk("manifest SI 识别", items3[1].kind == "si")

        # 7) 去重
        dd = dedupe_items([Item(doi="10.1002/x"), Item(doi="10.1002/X"), Item(doi="10.1002/y")])
        chk("按 DOI 去重", len(dd) == 2, str(len(dd)))

        # 8) 报告含可点击 DOI
        rep = render_report([Item(title="T", doi="10.1021/z", status="failed", reason="403")],
                            input_path=mf, mode="selftest", started=time.time(), known_skipped=0)
        chk("报告失败项带 DOI 链接", "](https://doi.org/10.1021/z)" in rep)

        # 9) 残余清单复用 lit_fetch.write_manifest（写临时目录）
        res = write_residual([Item(title="T", doi="10.1021/z", status="failed",
                                   reason="403", attempts=["403"])],
                             os.path.join(tmp, "residual.md"), "selftest", tmp)
        chk("残余清单可生成", bool(res) and os.path.exists(res), res)
        if res:
            txt = _read_text(res)
            chk("残余清单带可点击链接", "](http" in txt)

        # 10) 退出码：SI-only 输入不能被当成「正文全失败」
        chk("退出码 SI-only 全成功=0",
            exit_code_for([Item(kind="si", si_status="present")]) == 0)
        chk("退出码 SI-only 仍缺=3（不是 4）",
            exit_code_for([Item(kind="si", si_status="missing")]) == 3)
        chk("退出码 正文全失败=4",
            exit_code_for([Item(kind="main", status="failed")]) == 4)
        chk("退出码 正文部分成功=3",
            exit_code_for([Item(kind="main", status="ok"),
                           Item(kind="main", status="failed")]) == 3)

        # 11) profile 互斥锁：两个实例不能同时驱动同一 profile
        lk = os.path.join(tmp, "profile.lock")
        l1, l2 = ProfileLock(lk), ProfileLock(lk)
        chk("profile 锁：首个进程可获取", l1.acquire())
        chk("profile 锁：第二个进程被拒", not l2.acquire())
        l1.release()
        chk("profile 锁：释放后可再获取", l2.acquire())
        l2.release()
    finally:
        if tmp:
            shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{ok} ok, {fail} fail")
    print("lit_browser_fetch selftest: " + ("PASS" if fail == 0 else "FAIL"))
    return 0 if fail == 0 else 1


def main(argv: Optional[list[str]] = None) -> int:
    ap = build_parser()
    args = ap.parse_args(argv)
    if args.selftest:
        return selftest()
    if args.seed_from:
        return asyncio.run(seed_from_profile(args))
    if args.login:
        return asyncio.run(run_login(args))

    started = time.time()
    try:
        if args.doi:
            items = [Item(doi=_norm_doi(d), source="--doi") for d in args.doi]
            input_path = "--doi"
        elif args.input:
            input_path = _resolve(args.input)
            items = parse_input(input_path)
        elif args.latest:
            input_path = latest_input()
            items = parse_input(input_path)
        else:
            ap.print_help()
            print("\n[错误] 需要 --latest / --in / --doi 之一（或用 --selftest / --login）")
            return 2
    except Exception as e:  # noqa: BLE001
        print(f"[错误] 读取输入失败：{type(e).__name__}: {e}")
        return 2

    items = dedupe_items(items)
    if args.only:
        allow = {x.strip().lower() for x in args.only.split(",") if x.strip()}
        items = [x for x in items if classify_recipe(x.doi).key in allow]
    if args.skip:
        deny = {x.strip().lower() for x in args.skip.split(",") if x.strip()}
        items = [x for x in items if classify_recipe(x.doi).key not in deny]

    cache = MetaCache(_resolve(DEFAULT_META_CACHE_REL))
    enrich_items(items, cache, enabled=not args.no_metadata)
    cache.save()

    known = set() if args.no_dedup else _known_dois()
    pending = prefilter(items, known)
    skipped = [x for x in items if x.status == "skipped"]
    if args.limit and args.limit > 0:
        pending = pending[:args.limit]

    print_plan(pending, input_path, skipped, dry_run=not args.apply)
    if not args.apply:
        return 0
    if not pending:
        print("[完成] 没有待处理项")
        return 0

    rc = asyncio.run(run_browser(args, pending, input_path, started))
    if args.json:
        print(json.dumps([asdict(x) for x in pending], ensure_ascii=False, indent=1))
    return rc


if __name__ == "__main__":
    raise SystemExit(main())
